mapper.select:
SELECT accident_status
FROM accident_report
WHERE report_no = #{accidentNumber}

mapper.update:
UPDATE subrogation
SET
    subrogation_status = #{completedStatus},
    recovered_amount = #{recoveredAmount},
    recovered_at = #{recoveredAt},
    updated_at = #{recoveredAt}
WHERE report_no = #{accidentNumber}
  AND subrogation_status = #{currentStatus}
